import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export interface Job {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_status_available ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), at INTEGER NOT NULL);
  `);
  return db;
}

export function fromRow(row: Record<string, unknown>): Job {
  const result = row.result_output == null ? null : { output: String(row.result_output) };
  return {
    id: String(row.id), status: row.status as Job['status'], input: String(row.input),
    steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result, error: row.error == null ? null : String(row.error),
    createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export const jobSelect = `SELECT * FROM jobs`;
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, fromRow, jobSelect } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const send = (res: ServerResponse, status: number, body: unknown) => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
};
const error = (res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]) =>
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });

async function readBody(req: IncomingMessage): Promise<string> {
  let text = '';
  for await (const chunk of req) {
    text += chunk.toString();
    if (text.length > 100_000) throw new Error('too_large');
  }
  return text;
}

function jobById(id: string) {
  const row = db.prepare(`${jobSelect} WHERE id=?`).get(id) as Record<string, unknown> | undefined;
  return row ? fromRow(row) : null;
}

const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/' ) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as { at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - Number(row.at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare(`${jobSelect} ORDER BY created_at DESC, rowid DESC`).all() as Record<string, unknown>[];
      return send(res, 200, { jobs: rows.map(fromRow) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');

    const fields: {field:string;message:string}[] = [];
    const key = req.headers['idempotency-key'];
    const idemKey = Array.isArray(key) ? key[0] : key;
    if (idemKey !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(idemKey))
      fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
    if (!/^application\/json(?:\s*;|\s*$)/i.test(req.headers['content-type'] ?? ''))
      fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    let raw = '';
    try { raw = await readBody(req); } catch { fields.push({ field: 'body', message: 'Request body is too large.' }); }
    let body: unknown;
    if (!fields.some(f => f.field === 'body')) {
      try { body = JSON.parse(raw); } catch { fields.push({ field: 'body', message: 'Body must be valid JSON.' }); }
    }
    let input: unknown, steps: unknown, failAttempts: unknown;
    if (!fields.some(f => f.field === 'body')) {
      if (!body || typeof body !== 'object' || Array.isArray(body)) fields.push({ field: 'body', message: 'Body must be a JSON object.' });
      else {
        const object = body as Record<string, unknown>;
        for (const name of Object.keys(object)) if (!['input','steps','failAttempts'].includes(name)) fields.push({field:name,message:'Unknown field.'});
        input = object.input; steps = object.steps === undefined ? 5 : object.steps;
        failAttempts = object.failAttempts === undefined ? 0 : object.failAttempts;
        if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim().length === 0)
          fields.push({field:'input',message:'Must be a non-whitespace string of 1–1000 characters.'});
        if (!Number.isInteger(steps) || Number(steps) < 1 || Number(steps) > 20) fields.push({field:'steps',message:'Must be an integer from 1 to 20.'});
        if (!Number.isInteger(failAttempts) || Number(failAttempts) < 0 || Number(failAttempts) > 5) fields.push({field:'failAttempts',message:'Must be an integer from 0 to 5.'});
      }
    }
    if (fields.length) return error(res, 400, 'invalid_request', 'The request is invalid.', fields);
    const payload = JSON.stringify({ input, steps, failAttempts });
    const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (idemKey !== undefined) {
        const existing = db.prepare('SELECT payload,job_id FROM idempotency WHERE key=?').get(idemKey) as {payload:string;job_id:string} | undefined;
        if (existing) {
          db.exec('COMMIT');
          if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          const job = jobById(existing.job_id);
          if (job) return send(res, 200, job);
        }
      }
      const id = randomUUID();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?,?,?,?,?,0,0,?,?,0)`).run(id,'queued',input as string,steps as number,failAttempts as number,now,now);
      if (idemKey !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(idemKey,payload,id);
      db.exec('COMMIT');
      return send(res, 201, jobById(id));
    } catch (e) { db.exec('ROLLBACK'); throw e; }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return error(res,404,'not_found','Job not found.'); }
    const job = jobById(id);
    return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  return error(res, 404, 'not_found', 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown() { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A worker killed while owning a job leaves a durable running row. Requeue it for
// the same attempt number; progress is attempt-local and starts over at zero.
db.prepare(`UPDATE jobs SET status='queued', attempts=CASE WHEN attempts>0 THEN attempts-1 ELSE 0 END,
  progress_completed=0, updated_at=? WHERE status='running'`).run(new Date().toISOString());

const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,at) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch (e) { console.error('heartbeat failed', e); } }, 1000);
console.log('worker started');

async function processOne(): Promise<boolean> {
  db.exec('BEGIN IMMEDIATE');
  let row: {id:string;input:string;steps:number;fail_attempts:number;attempts:number} | undefined;
  try {
    row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
      WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1`).get(Date.now()) as typeof row;
    if (!row) { db.exec('COMMIT'); return false; }
    db.prepare(`UPDATE jobs SET status='running',attempts=attempts+1,progress_completed=0,
      error=NULL,result_output=NULL,updated_at=? WHERE id=? AND status='queued'`).run(new Date().toISOString(), row.id);
    row.attempts += 1;
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }

  if (row.attempts <= row.fail_attempts) {
    // Simulate the failing first step without publishing progress.
    await sleep(100);
    if (row.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed',progress_completed=0,error='transient failure',
        result_output=NULL,updated_at=? WHERE id=? AND status='running'`).run(new Date().toISOString(),row.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued',progress_completed=0,error=NULL,available_at=?,updated_at=?
        WHERE id=? AND status='running'`).run(Date.now()+500,new Date().toISOString(),row.id);
    }
    return true;
  }

  const stepDelay = 100;
  for (let completed=1; completed<=row.steps; completed++) {
    await sleep(stepDelay);
    if (stopping) {
      // Leave a recoverable running row for the next worker process.
      return true;
    }
    db.prepare('UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status=\'running\'')
      .run(completed,new Date().toISOString(),row.id);
  }
  db.prepare(`UPDATE jobs SET status='completed',progress_completed=steps,result_output=?,error=NULL,updated_at=?
    WHERE id=? AND status='running'`).run(row.input.toUpperCase(),new Date().toISOString(),row.id);
  return true;
}

try {
  while (!stopping) {
    const didWork = await processOne();
    if (!didWork) await sleep(100);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}
