<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label>Input <input data-testid="job-input" name="input" type="text" maxlength="1000" required></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0"></label>
    <div data-testid="form-error" role="alert"></div>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const list = document.querySelector('[data-testid="job-list"]');
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const input = document.querySelector('[data-testid="job-input"]');
    const steps = document.querySelector('[data-testid="job-steps"]');
    const failures = document.querySelector('[data-testid="job-fail-attempts"]');

    async function refresh() {
      try {
        const response = await fetch('/api/jobs');
        if (!response.ok) return;
        const { jobs } = await response.json();
        list.replaceChildren(...jobs.map(job => {
          const item = document.createElement('li');
          item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
          const title = document.createElement('strong'); title.textContent = job.input;
          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
          const progress = document.createElement('span'); progress.dataset.testid = 'job-progress';
          progress.textContent = `${job.progress.completed}/${job.progress.total}`;
          const result = document.createElement('div'); result.dataset.testid = 'job-result';
          result.textContent = job.result ? job.result.output : (job.error || '');
          const meta = document.createElement('div'); meta.className = 'meta';
          meta.append('Status: ', status, ' · Progress: ', progress);
          item.append(title, meta, result);
          return item;
        }));
      } catch { /* A later poll will retry if the server is temporarily unavailable. */ }
    }

    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      const payload = { input: input.value, steps: steps.value === '' ? null : Number(steps.value),
        failAttempts: failures.value === '' ? null : Number(failures.value) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error?.fields || [];
          errorRegion.textContent = fields.length
            ? fields.map(field => `${field.field}: ${field.message}`).join(' ')
            : (data.error?.message || 'Unable to submit job.');
        } else { input.value = ''; await refresh(); }
      } catch { errorRegion.textContent = 'Unable to submit job. Please try again.'; }
    });
    refresh(); setInterval(refresh, 1000);
  </script>
</body>
</html>
